(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[1191],{56271:function(n,e,o){Promise.resolve().then(o.bind(o,19538))},19538:function(n,e,o){"use strict";o.r(e),o.d(e,{default:function(){return t}});var a=o(57437);function t(){return(0,a.jsx)("div",{dangerouslySetInnerHTML:{__html:'<!DOCTYPE html>\n<html lang="pt-BR">\n<head>\n  <meta charset="UTF-8" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0" />\n  <title>Formul\xe1rio Pr\xe9-Consulta</title>\n  <style>\n    :root {\n      --azul: #1a4fa0;\n      --azul-claro: #e8f0fc;\n      --vermelho: #cc3300;\n      --cinza: #555;\n      --borda: #dce3ef;\n      --radius: 10px;\n    }\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body {\n      font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', sans-serif;\n      background: #f4f6fb;\n      color: #222;\n      min-height: 100vh;\n    }\n    header {\n      background: var(--azul);\n      color: white;\n      padding: 16px 20px 14px;\n    }\n    header h1 { font-size: 17px; font-weight: 700; }\n    header p  { font-size: 12px; opacity: .85; margin-top: 2px; }\n\n    .progresso {\n      background: white;\n      border-bottom: 1px solid var(--borda);\n      padding: 12px 20px;\n      position: sticky;\n      top: 0;\n      z-index: 10;\n    }\n    .prog-dots {\n      display: flex;\n      gap: 8px;\n      align-items: center;\n      margin-bottom: 4px;\n    }\n    .dot {\n      width: 10px; height: 10px;\n      border-radius: 50%;\n      background: #cdd5e0;\n      transition: background .3s;\n    }\n    .dot.ativo   { background: var(--azul); }\n    .dot.feito   { background: #27ae60; }\n    .prog-texto  { font-size: 12px; color: var(--cinza); }\n    .prog-bar    { height: 4px; background: #e0e4ee; border-radius: 2px; margin-top: 8px; }\n    .prog-fill   { height: 100%; background: var(--azul); border-radius: 2px; transition: width .4s; }\n\n    main { max-width: 520px; margin: 0 auto; padding: 0 16px 100px; }\n\n    .secao {\n      display: none;\n      padding-top: 20px;\n    }\n    .secao.ativa { display: block; }\n\n    .secao-titulo {\n      font-size: 15px;\n      font-weight: 700;\n      color: var(--azul);\n      margin-bottom: 16px;\n      padding-bottom: 8px;\n      border-bottom: 2px solid var(--azul-claro);\n    }\n\n    .campo { margin-bottom: 16px; }\n    label {\n      display: block;\n      font-size: 13px;\n      font-weight: 600;\n      color: var(--cinza);\n      margin-bottom: 5px;\n    }\n    label .opt { font-weight: 400; color: #999; }\n\n    input[type=text],\n    input[type=date],\n    input[type=number],\n    select,\n    textarea {\n      width: 100%;\n      padding: 11px 13px;\n      border: 1.5px solid var(--borda);\n      border-radius: var(--radius);\n      font-size: 15px;\n      color: #222;\n      background: white;\n      transition: border-color .2s;\n      -webkit-appearance: none;\n    }\n    input:focus, select:focus, textarea:focus {\n      outline: none;\n      border-color: var(--azul);\n    }\n    textarea { min-height: 80px; resize: vertical; }\n\n    input[readonly], select[disabled] {\n      background: #f0f3f9;\n      color: #666;\n    }\n\n    .slider-wrap { position: relative; padding-bottom: 20px; }\n    input[type=range] {\n      width: 100%;\n      -webkit-appearance: none;\n      height: 8px;\n      border-radius: 4px;\n      background: linear-gradient(to right, var(--azul) 0%, var(--azul) 0%, #dce3ef 0%);\n      border: none;\n      padding: 0;\n    }\n    input[type=range]::-webkit-slider-thumb {\n      -webkit-appearance: none;\n      width: 24px; height: 24px;\n      border-radius: 50%;\n      background: var(--azul);\n      cursor: pointer;\n      border: 3px solid white;\n      box-shadow: 0 0 4px rgba(0,0,0,.25);\n    }\n    .slider-labels {\n      display: flex;\n      justify-content: space-between;\n      font-size: 11px;\n      color: #999;\n      margin-top: 4px;\n    }\n    .eva-val {\n      text-align: center;\n      font-size: 28px;\n      font-weight: 700;\n      color: var(--azul);\n      line-height: 1;\n    }\n    .eva-desc {\n      text-align: center;\n      font-size: 12px;\n      color: var(--cinza);\n      margin-top: 2px;\n    }\n\n    .radio-group, .check-group {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 8px;\n    }\n    .radio-group label, .check-group label {\n      display: flex;\n      align-items: center;\n      gap: 6px;\n      background: white;\n      border: 1.5px solid var(--borda);\n      border-radius: 20px;\n      padding: 7px 14px;\n      font-size: 14px;\n      font-weight: 500;\n      color: #333;\n      cursor: pointer;\n      transition: border-color .15s, background .15s;\n      margin-bottom: 0;\n    }\n    .radio-group input, .check-group input { display: none; }\n    .radio-group label:has(input:checked),\n    .check-group label:has(input:checked) {\n      border-color: var(--azul);\n      background: var(--azul-claro);\n      color: var(--azul);\n    }\n\n    .campo-duplo { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n    .cep-aviso { font-size: 13px; margin-top: 6px; min-height: 18px; }\n    .cep-aviso.ok  { color: #0f7a4d; }\n    .cep-aviso.err { color: var(--vermelho); }\n    .spinner {\n      display: none;\n      width: 18px; height: 18px;\n      border: 2px solid var(--borda);\n      border-top-color: var(--azul);\n      border-radius: 50%;\n      animation: spin .7s linear infinite;\n    }\n    @keyframes spin { to { transform: rotate(360deg); } }\n\n    .botoes {\n      position: fixed;\n      bottom: 0; left: 0; right: 0;\n      background: white;\n      border-top: 1px solid var(--borda);\n      padding: 12px 20px;\n      display: flex;\n      gap: 10px;\n      max-width: 520px;\n      margin: 0 auto;\n    }\n    @media (min-width: 552px) {\n      .botoes { left: 50%; right: auto; transform: translateX(-50%); width: 520px; }\n    }\n\n    button {\n      flex: 1;\n      padding: 14px;\n      border: none;\n      border-radius: var(--radius);\n      font-size: 15px;\n      font-weight: 700;\n      cursor: pointer;\n      transition: opacity .2s;\n    }\n    button:disabled { opacity: .5; cursor: not-allowed; }\n    .btn-prox { background: var(--azul); color: white; }\n    .btn-ant  { background: #eef1f7; color: #444; flex: 0 0 80px; }\n    .btn-enviar { background: #27ae60; color: white; }\n\n    .erro-campo {\n      font-size: 12px;\n      color: var(--vermelho);\n      margin-top: 4px;\n      display: none;\n    }\n    .campo.invalido input,\n    .campo.invalido select,\n    .campo.invalido textarea {\n      border-color: var(--vermelho);\n    }\n    .campo.invalido .erro-campo { display: block; }\n\n    .info-box {\n      background: #fff8e1;\n      border: 1px solid #ffe082;\n      border-radius: var(--radius);\n      padding: 12px 14px;\n      font-size: 13px;\n      color: #7a5c00;\n      margin-bottom: 16px;\n    }\n\n    #tela-expirado {\n      display: none;\n      text-align: center;\n      padding: 60px 24px;\n    }\n    #tela-expirado .icon { font-size: 52px; margin-bottom: 16px; }\n    #tela-expirado h2 { font-size: 18px; color: #333; margin-bottom: 10px; }\n    #tela-expirado p  { font-size: 14px; color: #666; margin-bottom: 24px; }\n    #tela-expirado a {\n      display: inline-block;\n      background: #25d366;\n      color: white;\n      text-decoration: none;\n      padding: 14px 28px;\n      border-radius: 30px;\n      font-weight: 700;\n      font-size: 15px;\n    }\n  </style>\n</head>\n<body>\n\n<div id="tela-expirado">\n  <div class="icon">⏰</div>\n  <h2>Link n\xe3o est\xe1 mais dispon\xedvel</h2>\n  <p>Este link n\xe3o est\xe1 mais dispon\xedvel. Sem problema — entre em contato pelo WhatsApp e reenviamos em instantes.</p>\n  <a href="https://wa.me/5581999179609">Falar com a cl\xednica →</a>\n</div>\n\n<div id="app" style="display:none">\n\n  <header>\n    <h1 id="cab-unidade">Formul\xe1rio Pr\xe9-Consulta</h1>\n    <p>Dr. Valth Menezes Guimar\xe3es \xb7 <span id="cab-crm">CRM-PB 6326</span></p>\n  </header>\n\n  <div class="progresso">\n    <div class="prog-dots">\n      <span class="prog-texto">⚡ Rapidinho: leva menos de 1 minuto</span>\n    </div>\n  </div>\n\n  <main>\n\n    <!-- Bloco 1: Identifica\xe7\xe3o -->\n    <div class="secao ativa" id="sec1">\n      <div class="secao-titulo">Identifica\xe7\xe3o</div>\n\n      <div class="campo" id="c-nasc">\n        <label>Data de nascimento</label>\n        <input type="date" id="nascimento" />\n        <div class="erro-campo">Informe sua data de nascimento.</div>\n      </div>\n\n      <div class="campo">\n        <label>Sexo</label>\n        <div class="radio-group" id="grupo-sexo">\n          <label><input type="radio" name="sexo" value="F" /> Feminino</label>\n          <label><input type="radio" name="sexo" value="M" /> Masculino</label>\n        </div>\n      </div>\n\n      <div class="campo" id="c-cpf">\n        <label>CPF</label>\n        <input type="text" id="cpf" inputmode="numeric" placeholder="000.000.000-00" />\n        <div class="erro-campo">Informe seu CPF.</div>\n      </div>\n\n      <div class="campo">\n        <label>Profiss\xe3o <span class="opt">(opcional)</span></label>\n        <input type="text" id="profissao" placeholder="Ex: professora, agricultor…" />\n      </div>\n\n      <div class="campo" id="c-cep">\n        <label>CEP <span class="opt">(o endere\xe7o aparece sozinho)</span></label>\n        <input type="text" id="cep" inputmode="numeric" placeholder="00000-000" />\n        <div class="cep-aviso" id="cep-aviso"></div>\n      </div>\n\n      <div class="campo">\n        <label>Rua</label>\n        <input type="text" id="logradouro" placeholder="Preenchido pelo CEP" />\n      </div>\n\n      <div class="campo-duplo">\n        <div class="campo">\n          <label>N\xfamero</label>\n          <input type="text" id="numero" placeholder="123" />\n        </div>\n        <div class="campo">\n          <label>Complemento <span class="opt">(opcional)</span></label>\n          <input type="text" id="complemento" placeholder="Apto 202" />\n        </div>\n      </div>\n\n      <div class="campo">\n        <label>Bairro</label>\n        <input type="text" id="bairro" placeholder="Preenchido pelo CEP" />\n      </div>\n\n      <div class="campo-duplo">\n        <div class="campo">\n          <label>Cidade</label>\n          <input type="text" id="cidade" placeholder="Preenchido pelo CEP" />\n        </div>\n        <div class="campo">\n          <label>UF</label>\n          <input type="text" id="uf" maxlength="2" placeholder="PE" />\n        </div>\n      </div>\n    </div>\n\n    <!-- Bloco 2: Queixa -->\n    <div class="secao ativa">\n      <div class="secao-titulo">Queixa</div>\n\n      <div class="campo" id="c-regiao">\n        <label>Regi\xe3o do corpo afetada</label>\n        <select id="regiao_corpo">\n          <option value="">Selecione…</option>\n          <option value="joelho_dir">Joelho direito</option>\n          <option value="joelho_esq">Joelho esquerdo</option>\n          <option value="quadril">Quadril</option>\n          <option value="ombro">Ombro</option>\n          <option value="tornozelo">Tornozelo</option>\n          <option value="coluna">Coluna</option>\n          <option value="mao_punho">M\xe3o / Punho</option>\n          <option value="outro">Outro</option>\n        </select>\n        <div class="erro-campo">Por favor, selecione a regi\xe3o.</div>\n      </div>\n\n      <div class="campo" id="c-desc">\n        <label>Descreva com suas palavras o que est\xe1 sentindo</label>\n        <textarea id="descricao" placeholder="Ex: Dor ao subir escadas, incha\xe7o no joelho…" rows="3"></textarea>\n        <div class="erro-campo">Por favor, descreva o que est\xe1 sentindo.</div>\n      </div>\n\n      <div class="campo">\n        <label>H\xe1 quanto tempo tem esses sintomas?</label>\n        <select id="tempo_sintomas">\n          <option value="">Selecione…</option>\n          <option value="menos_1sem">Menos de 1 semana</option>\n          <option value="1_4sem">1 a 4 semanas</option>\n          <option value="1_6meses">1 a 6 meses</option>\n          <option value="mais_6meses">Mais de 6 meses</option>\n          <option value="mais_1ano">Mais de 1 ano</option>\n        </select>\n      </div>\n\n      <div class="campo">\n        <label>Intensidade da dor agora</label>\n        <div class="slider-wrap">\n          <div class="eva-val" id="eva-val">5</div>\n          <div class="eva-desc" id="eva-desc">Dor moderada</div>\n          <input type="range" id="eva" min="0" max="10" value="5" />\n          <div class="slider-labels"><span>0 – Sem dor</span><span>10 – Dor m\xe1xima</span></div>\n        </div>\n      </div>\n    </div>\n\n    <!-- Bloco 3: Sa\xfade geral -->\n    <div class="secao ativa">\n      <div class="secao-titulo">Sa\xfade geral</div>\n\n      <div class="campo">\n        <label>Doen\xe7as que voc\xea tem <span class="opt">(marque as que se aplicam)</span></label>\n        <div class="check-group">\n          <label><input type="checkbox" name="doencas" value="has" /> Press\xe3o alta</label>\n          <label><input type="checkbox" name="doencas" value="dm" /> Diabetes</label>\n          <label><input type="checkbox" name="doencas" value="osteoporose" /> Osteoporose</label>\n          <label><input type="checkbox" name="doencas" value="artrite" /> Artrite</label>\n          <label><input type="checkbox" name="doencas" value="artrose" /> Artrose</label>\n          <label><input type="checkbox" name="doencas" value="outra" /> Outra</label>\n        </div>\n      </div>\n\n      <div class="campo">\n        <label>Medica\xe7\xf5es em uso cont\xednuo <span class="opt">(opcional)</span></label>\n        <input type="text" id="medicacoes" placeholder="Ex: Losartana 50mg, AAS 100mg" />\n      </div>\n\n      <div class="campo">\n        <label>Alergias a medicamentos <span class="opt">(especialmente dipirona / anti-inflamat\xf3rios)</span></label>\n        <input type="text" id="alergias" placeholder="Ex: Dipirona — ou \'nenhuma conhecida\'" />\n      </div>\n\n      <div class="campo">\n        <label>Cirurgias anteriores <span class="opt">(opcional)</span></label>\n        <input type="text" id="cirurgias_anteriores" placeholder="Ex: menisco joelho direito, 2019" />\n      </div>\n    </div>\n\n    <!-- Bloco 4: Pagamento -->\n    <div class="secao ativa">\n      <div class="secao-titulo">Pagamento</div>\n\n      <div class="campo">\n        <label>Como vai pagar a consulta?</label>\n        <div class="radio-group" id="forma_pagamento">\n          <label><input type="radio" name="pagamento" value="particular" /> Particular</label>\n          <label><input type="radio" name="pagamento" value="convenio" /> Conv\xeanio / plano</label>\n        </div>\n      </div>\n\n      <div class="campo" id="campo-plano" style="display:none">\n        <label>Qual plano de sa\xfade?</label>\n        <input type="text" id="plano_saude" placeholder="Ex: Unimed, Bradesco Sa\xfade…" />\n      </div>\n    </div>\n\n  </main>\n\n  <div class="botoes" id="botoes">\n    <button class="btn-enviar" id="btn-prox" onclick="enviar()">✓ Enviar</button>\n  </div>\n\n</div>\n\n<script>\nconst params = new URLSearchParams(location.search);\nconst NOME        = params.get(\'nome\')   || \'\';\nconst TEL         = params.get(\'tel\')    || \'\';\nconst DATA        = params.get(\'data\')   || \'\';\nconst MOTIVO      = params.get(\'motivo\') || \'\';\nconst AID         = params.get(\'aid\')    || \'\';\nconst EXP         = params.get(\'exp\')    || \'\';\nconst TOKEN       = params.get(\'token\')  || \'\';\nconst UNIDADE     = params.get(\'unidade\')|| \'\';\n\n// A unidade vem no link do agendamento. Nunca mais escrever "CTO" fixo: era\n// isso que fazia o paciente do IP abrir uma pagina com o nome de outra clinica.\nconst UNIDADES = [\n  { chaves: [\'artro\'],                                  nome: \'Cl\xednica Artro\',             uf: \'PB\' },\n  { chaves: [\'cto\'],                                    nome: \'Cl\xednica CTO\',               uf: \'PB\' },\n  { chaves: [\'pernambuco\', \'instituto pe\', \'ip\'],       nome: \'Instituto Pernambuco (IP)\', uf: \'PE\' },\n  { chaves: [\'unimagem\'],                               nome: \'Cl\xednica Unimagem\',          uf: \'PE\' },\n  { chaves: [\'mario bento\', \'m\xe1rio bento\', \'palmares\'], nome: \'Cl\xednica M\xe1rio Bento\',       uf: \'PE\' },\n];\nconst CRM = { PB: \'CRM-PB 6326\', PE: \'CREMEPE 16.551\' };\n\nfunction semAcento(t) {\n  return (t || \'\').toLowerCase().normalize(\'NFD\').replace(/[̀-ͯ]/g, \'\');\n}\n\nfunction aplicarCabecalho() {\n  const texto = \' \' + semAcento(UNIDADE) + \' \';\n  const u = UNIDADES.find(x => x.chaves.some(c => texto.includes(semAcento(c))));\n  if (!u) return;\n  document.getElementById(\'cab-unidade\').textContent = u.nome + \' – Formul\xe1rio Pr\xe9-Consulta\';\n  document.getElementById(\'cab-crm\').textContent = CRM[u.uf];\n  document.title = \'Pr\xe9-Consulta – \' + u.nome;\n}\n\nfunction init() {\n  if (!TOKEN || !EXP || !AID) {\n    mostrarExpirado();\n    return;\n  }\n  if (Date.now() > parseInt(EXP)) {\n    mostrarExpirado();\n    return;\n  }\n\n  document.getElementById(\'app\').style.display = \'block\';\n\n  // Identifica\xe7\xe3o vem do agendamento (link do WhatsApp) — n\xe3o perguntamos de novo.\n  if (NOME) {\n    const t = document.querySelector(\'.secao-titulo\');\n    if (t) t.textContent = \'Ol\xe1, \' + NOME.split(\' \')[0] + \'! Conte sobre sua queixa\';\n  }\n\n  const sel = document.getElementById(\'regiao_corpo\');\n  for (const opt of sel.options) {\n    // opt.value vazio ("Selecione…") casaria com qualquer motivo — pular.\n    if (opt.value && MOTIVO.toLowerCase().includes(opt.value.replace(\'_\',\' \'))) {\n      opt.selected = true;\n      break;\n    }\n  }\n\n  aplicarCabecalho();\n  initEva();\n  initCep();\n  initPagamento();\n}\n\nfunction mostrarExpirado() {\n  document.getElementById(\'tela-expirado\').style.display = \'block\';\n}\n\nconst EVA_DESC = [\'Sem dor\',\'Dor m\xednima\',\'Dor leve\',\'Dor leve\',\'Dor moderada\',\'Dor moderada\',\n                  \'Dor intensa\',\'Dor intensa\',\'Dor muito intensa\',\'Dor severa\',\'Dor m\xe1xima\'];\nfunction initEva() {\n  const slider = document.getElementById(\'eva\');\n  function atualizar() {\n    const v = parseInt(slider.value);\n    document.getElementById(\'eva-val\').textContent  = v;\n    document.getElementById(\'eva-desc\').textContent = EVA_DESC[v];\n    const pct = (v / 10) * 100;\n    slider.style.background =\n      \'linear-gradient(to right, var(--azul) \' + pct + \'%, #dce3ef \' + pct + \'%)\';\n  }\n  slider.addEventListener(\'input\', atualizar);\n  atualizar();\n}\n\nfunction initCep() {\n  const inp = document.getElementById(\'cep\');\n  const aviso = document.getElementById(\'cep-aviso\');\n  inp.addEventListener(\'input\', () => {\n    const d = inp.value.replace(/D/g, \'\').slice(0, 8);\n    inp.value = d.length > 5 ? d.slice(0, 5) + \'-\' + d.slice(5) : d;\n    if (d.length === 8) buscarCep(d, aviso);\n    else aviso.textContent = \'\';\n  });\n}\n\nasync function buscarCep(cep, aviso) {\n  aviso.className = \'cep-aviso\';\n  aviso.textContent = \'Buscando endere\xe7o…\';\n  try {\n    const res = await fetch(\'https://viacep.com.br/ws/\' + cep + \'/json/\');\n    const d = await res.json();\n    if (d.erro) {\n      aviso.className = \'cep-aviso err\';\n      aviso.textContent = \'CEP n\xe3o encontrado — pode preencher \xe0 m\xe3o.\';\n      return;\n    }\n    // Cidades pequenas tem CEP unico: vem so a cidade, sem rua/bairro. Nao\n    // apagamos o que o paciente ja digitou nesse caso.\n    if (d.logradouro) document.getElementById(\'logradouro\').value = d.logradouro;\n    if (d.bairro)     document.getElementById(\'bairro\').value     = d.bairro;\n    document.getElementById(\'cidade\').value = d.localidade || \'\';\n    document.getElementById(\'uf\').value     = d.uf || \'\';\n    aviso.className = \'cep-aviso ok\';\n    aviso.textContent = d.logradouro ? \'✓ endere\xe7o encontrado\'\n                                     : \'✓ cidade encontrada — complete a rua e o bairro\';\n    document.getElementById(\'numero\').focus();\n  } catch {\n    aviso.className = \'cep-aviso err\';\n    aviso.textContent = \'N\xe3o consegui buscar agora — pode preencher \xe0 m\xe3o.\';\n  }\n}\n\nfunction initPagamento() {\n  document.querySelectorAll(\'input[name="pagamento"]\').forEach(r => {\n    r.addEventListener(\'change\', () => {\n      document.getElementById(\'campo-plano\').style.display =\n        r.value === \'convenio\' ? \'block\' : \'none\';\n    });\n  });\n}\n\nfunction validarCampo(idCampo, idInput) {\n  const campo = document.getElementById(idCampo);\n  const inp   = document.getElementById(idInput);\n  if (!inp) return true;\n  const vazio = !inp.value || inp.value.trim() === \'\';\n  campo.classList.toggle(\'invalido\', vazio);\n  return !vazio;\n}\n\nasync function enviar() {\n  // Obrigatorios (Valth 19/08: CPF e nascimento SEMPRE, de todo paciente).\n  const ok = validarCampo(\'c-nasc\', \'nascimento\') &\n             validarCampo(\'c-cpf\', \'cpf\') &\n             validarCampo(\'c-regiao\', \'regiao_corpo\') &\n             validarCampo(\'c-desc\', \'descricao\');\n  if (!ok) {\n    const inv = document.querySelector(\'.campo.invalido\');\n    if (inv) inv.scrollIntoView({ behavior: \'smooth\', block: \'center\' });\n    return;\n  }\n  const btnProx = document.getElementById(\'btn-prox\');\n  btnProx.disabled = true;\n  btnProx.textContent = \'Enviando…\';\n\n  const pagamento = document.querySelector(\'input[name="pagamento"]:checked\');\n  const doencas   = Array.from(document.querySelectorAll(\'input[name="doencas"]:checked\')).map(i => i.value);\n\n  // Identifica\xe7\xe3o (nome/tel/unidade/data) vem do link do agendamento — sem re-perguntar.\n  // Campos cortados da folha \xfanica v\xe3o vazios (backend trata todos como opcionais).\n  const payload = {\n    token: TOKEN,\n    exp: EXP,\n    agendamento_id: AID,\n    nome:           NOME,\n    telefone:       TEL,\n    data_consulta:  DATA,\n    nascimento:     document.getElementById(\'nascimento\').value,\n    sexo:           (document.querySelector(\'input[name="sexo"]:checked\') || {}).value || null,\n    cpf:            document.getElementById(\'cpf\').value,\n    cidade:         document.getElementById(\'cidade\').value,\n    unidade:        UNIDADE,\n    bairro:         document.getElementById(\'bairro\').value,\n    profissao:      document.getElementById(\'profissao\').value,\n    estado_civil:   \'\',\n    filhos:         0,\n    cep:            document.getElementById(\'cep\').value,\n    logradouro:     document.getElementById(\'logradouro\').value,\n    numero:         document.getElementById(\'numero\').value,\n    complemento:    document.getElementById(\'complemento\').value,\n    uf:             document.getElementById(\'uf\').value,\n    doencas_cronicas: doencas,\n    medicacoes:         document.getElementById(\'medicacoes\').value,\n    alergias:           document.getElementById(\'alergias\').value,\n    cirurgias_anteriores: document.getElementById(\'cirurgias_anteriores\').value,\n    tabagismo:      \'\',\n    alcool:         \'\',\n    regiao_corpo:   document.getElementById(\'regiao_corpo\').value,\n    descricao:      document.getElementById(\'descricao\').value,\n    tempo_sintomas: document.getElementById(\'tempo_sintomas\').value,\n    mecanismo:      \'\',\n    eva:            parseInt(document.getElementById(\'eva\').value),\n    piora:          \'\',\n    melhora:        \'\',\n    tratamento_anterior: \'\',\n    uso_analgesicos:     \'\',\n    exames_urls:    [],\n    forma_pagamento: pagamento ? pagamento.value : \'particular\',\n    plano_saude:    document.getElementById(\'plano_saude\').value || null,\n  };\n\n  try {\n    const res = await fetch(\'/pre-consulta/submit\', {\n      method: \'POST\',\n      headers: { \'Content-Type\': \'application/json\' },\n      body: JSON.stringify(payload),\n    });\n\n    if (!res.ok) {\n      const { erro, token_expirado } = await res.json();\n      if (token_expirado) { mostrarExpirado(); return; }\n      alert(\'Erro ao enviar: \' + erro);\n      btnProx.disabled = false;\n      btnProx.textContent = \'✓ Enviar formul\xe1rio\';\n      return;\n    }\n\n    const dataFmt = DATA ? new Date(DATA).toLocaleDateString(\'pt-BR\') : \'\';\n    const horaFmt = DATA ? new Date(DATA).toLocaleTimeString(\'pt-BR\',{hour:\'2-digit\',minute:\'2-digit\'}) : \'\';\n    location.href = \'/confirmacao?nome=\' + encodeURIComponent(NOME) + \'&data=\' + encodeURIComponent(dataFmt) + \'&hora=\' + encodeURIComponent(horaFmt);\n  } catch {\n    alert(\'Falha de rede. Verifique sua conex\xe3o e tente novamente.\');\n    btnProx.disabled = false;\n    btnProx.textContent = \'✓ Enviar formul\xe1rio\';\n  }\n}\n\ninit();\n</script>\n</body>\n</html>'},style:{all:"unset"}})}},30622:function(n,e,o){"use strict";var a=o(2265),t=Symbol.for("react.element"),i=Symbol.for("react.fragment"),r=Object.prototype.hasOwnProperty,l=a.__SECRET_INTERNALS_DO_NOT_USE_OR_YOU_WILL_BE_FIRED.ReactCurrentOwner,d={key:!0,ref:!0,__self:!0,__source:!0};function s(n,e,o){var a,i={},s=null,c=null;for(a in void 0!==o&&(s=""+o),void 0!==e.key&&(s=""+e.key),void 0!==e.ref&&(c=e.ref),e)r.call(e,a)&&!d.hasOwnProperty(a)&&(i[a]=e[a]);if(n&&n.defaultProps)for(a in e=n.defaultProps)void 0===i[a]&&(i[a]=e[a]);return{$$typeof:t,type:n,key:s,ref:c,props:i,_owner:l.current}}e.Fragment=i,e.jsx=s,e.jsxs=s},57437:function(n,e,o){"use strict";n.exports=o(30622)}},function(n){n.O(0,[2971,4938,1744],function(){return n(n.s=56271)}),_N_E=n.O()}]);